insert into gw_audit_log(business_type,business_id,action,operator_id,before_data,after_data,reason,create_time)
values('ASSIGNMENT',#{businessId},#{action},#{operatorId},
       if(#{beforeWorkstationId} is null,null,json_object('studentId',#{studentId},'workstationId',#{beforeWorkstationId})),
       if(#{afterWorkstationId} is null,null,json_object('studentId',#{studentId},'workstationId',#{afterWorkstationId})),
       #{reason},now())
